-- Catalog and ledger only. Does not read account or question content.
SELECT (EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261025000000' AND name='question_practice_review_history' AND cardinality(statements)=1 AND md5(statements[1])='dbb06ac25eebc2319a3543505c1dff36') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261026000000' AND name='question_practice_adaptation_v2' AND cardinality(statements)=1 AND md5(statements[1])='354934137b8be264f4b1b2cf58d36b2e') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261028000000' AND name='course_topic_practice' AND cardinality(statements)=1 AND md5(statements[1])='f8d0fd626747b1dd42fd6f03cf285591') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261104000000' AND name='question_practice_continuous' AND cardinality(statements)=1 AND md5(statements[1])='5812dd9d82c6474144ed67d24d83da65')) AS prerequisite_ledger_matches,(coalesce((SELECT md5(prosrc)='a18312b9fe60c31fbdde267d9241e6ae' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_signals()')),false) AND coalesce((SELECT md5(prosrc)='d4088db3fa9026ae6dd0017bc05e6295' FROM pg_proc WHERE oid=to_regprocedure('public.submit_question_practice_v2(uuid,uuid,uuid,integer,jsonb,boolean)')),false) AND coalesce((SELECT md5(prosrc)='d44924032760bb633e96c245b4269b7b' FROM pg_proc WHERE oid=to_regprocedure('public.start_question_practice_in_scope(uuid,uuid,uuid)')),false) AND coalesce((SELECT md5(prosrc)='87bfa6d1ad3249b4e5158346fc19c08e' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_topic_status(uuid)')),false) AND coalesce((SELECT md5(prosrc)='f86fc1b913213860973bcde5bc70308f' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_continuous_pool(uuid)')),false) AND coalesce((SELECT md5(prosrc)='5765991cdb57155b535bed5bb3a5259e' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_continuous_state(uuid)')),false) AND coalesce((SELECT md5(prosrc)='75620c466e8819f8f4ae007d71e034cc' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_snapshot(uuid)')),false) AND coalesce((SELECT md5(prosrc)='affd424769333db5be07a9e96f247ca4' FROM pg_proc WHERE oid=to_regprocedure('public.list_question_practice_attempts(boolean)')),false)) AS prerequisite_functions_match,(NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261105000000') AND to_regclass('public.arena_practice_issues') IS NULL AND NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_sessions' AND column_name='source') AND to_regprocedure('public.arena_practice_pool()') IS NULL AND to_regprocedure('public.arena_practice_payload(uuid)') IS NULL AND to_regprocedure('public.arena_practice_catalog()') IS NULL AND to_regprocedure('public.arena_practice_next_question(uuid,integer[],integer,integer,boolean)') IS NULL AND to_regprocedure('public.arena_practice_submit_answer(uuid,integer)') IS NULL AND to_regprocedure('public.get_question_practice_statistics(uuid)') IS NULL) AS integration_absent;
